def test_req006_acquire_run_slot_honors_provider_cap(tmp_path):
    """REQ-006: with a provider cap of 1 and one active entry, a second
    acquire must time out rather than over-admit."""
    reg = tmp_path / "registry.json"
    IR.acquire_run_slot(
        runner="claude", harness_run_dir=tmp_path, run_index=0,
        started_at="2026-05-30T21:00:00Z", max_per_provider={"anthropic": 1},
        registry_path=reg, max_wait_s=0.0,
    )
    IR.update_pid(harness_run_dir=tmp_path, run_index=0, pid=os.getpid(), registry_path=reg)
    with pytest.raises(TimeoutError):
        IR.acquire_run_slot(
            runner="claude", harness_run_dir=tmp_path, run_index=1,
            started_at="2026-05-30T21:00:01Z", max_per_provider={"anthropic": 1},
            registry_path=reg, max_wait_s=0.3, poll_interval_s=0.05,
        )


def test_req008_write_terminal_status_preserves_existing(tmp_path):
    """REQ-008: the collector must not overwrite a status.json that already
    carries a terminal_state (the supervisor's richer write wins)."""
    run_dir = tmp_path / "run-00"
    run_dir.mkdir()
    (run_dir / "status.json").write_text(json.dumps({
        "state": "DONE", "terminal_state": "ABORTED_PHASE",
        "exit_code": 1, "phase_aborted": 2, "terminal_reason": "quota",
    }), encoding="utf-8")
    PR._write_terminal_status(run_dir, pid=123, started_at="x", ended_at="y",
                              terminal=TerminalState.FAILED, terminal_reason="")
    after = json.loads((run_dir / "status.json").read_text(encoding="utf-8"))
    assert after["terminal_state"] == "ABORTED_PHASE"
    assert after["exit_code"] == 1


def test_req009_stale_quality_dir_requires_recent_marker(tmp_path):
    """REQ-009: a populated quality/ with no recent run_start is stale;
    one with a fresh run_start marker is not."""
    q = tmp_path / "quality"
    q.mkdir()
    (q / "BUGS.md").write_text("# bugs\n", encoding="utf-8")
    stale = QV.check_stale_quality_dir(tmp_path)
    assert stale and stale[0]["code"] == "stale_quality_dir"
    # Add a fresh run_start marker → no longer stale.
    from datetime import datetime, timezone
    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    (q / "run_state.jsonl").write_text(
        json.dumps({"event": "run_start", "ts": now}) + "\n", encoding="utf-8")
    assert QV.check_stale_quality_dir(tmp_path) == []


def test_req010_council_members_falls_back_on_malformed(monkeypatch):
    """REQ-010: a malformed council_members override falls back to defaults."""
    import bin.qpb_config as QC
    monkeypatch.setattr(QC, "load_config", lambda: {"council_members": []})
    assert CC.council_members() == CC.DEFAULT_COUNCIL_MEMBERS
    monkeypatch.setattr(QC, "load_config", lambda: {"council_members": "not-a-list"})
    assert CC.council_members() == CC.DEFAULT_COUNCIL_MEMBERS


