def test_req012_validate_no_source_edits_flags_outside_quality(tmp_path):
    """REQ-012: a dirty file outside quality/ is a violation; one under
    quality/ is clean."""
    subprocess.run(["git", "init", "-q"], cwd=tmp_path, check=True)
    subprocess.run(["git", "config", "user.email", "t@t.t"], cwd=tmp_path, check=True)
    subprocess.run(["git", "config", "user.name", "t"], cwd=tmp_path, check=True)
    (tmp_path / "src.py").write_text("x=1\n", encoding="utf-8")
    subprocess.run(["git", "add", "-A"], cwd=tmp_path, check=True)
    subprocess.run(["git", "commit", "-qm", "init"], cwd=tmp_path, check=True)
    # Dirty a source file outside quality/.
    (tmp_path / "src.py").write_text("x=2\n", encoding="utf-8")
    ok, viol = RSL.validate_no_source_edits(tmp_path)
    assert ok is False and "src.py" in viol
    # Clean it; dirty only under quality/.
    (tmp_path / "src.py").write_text("x=1\n", encoding="utf-8")
    (tmp_path / "quality").mkdir()
    (tmp_path / "quality" / "out.md").write_text("ok\n", encoding="utf-8")
    ok2, viol2 = RSL.validate_no_source_edits(tmp_path)
    assert ok2 is True and viol2 == []


