@pytest.mark.xfail(strict=False, reason="REQ-001: collector grades PENDING/pid=None as FAILED on first sweep (BUG-001)")
def test_req001_pending_pidless_not_graded_failed(tmp_path):
    """REQ-001: a within-deadline PENDING/pid=None entry must NOT be graded FAILED."""
    hr = tmp_path
    (hr / "run-00").mkdir()
    entry = {
        "index": 0, "description": "d", "repo": "r", "runner": "claude",
        "model": "opus", "channel": "clone", "mode": "A",
        "run_dir": str(hr / "run-00"), "target_dir": str(hr / "run-00" / "target"),
        "pid": None, "state": "PENDING", "started_at": "", "expect": {},
        "max_duration_s": 3600.0, "stream_path": str(hr / "run-00" / "stream.ndjson"),
    }
    outcome = PR._collect_one_run_detached(entry, hr)
    assert outcome.terminal_state != TerminalState.FAILED.value, (
        "a waiting PENDING/pid=None run within its deadline must not be graded FAILED")


