def test_req007_idempotency_short_circuits_on_grading_json(tmp_path):
    """REQ-007 boundary: with a valid grading.json present, _collect_one_run_detached
    returns the cached verdict without re-polling (idempotency contract C-02)."""
    hr = tmp_path
    rd = hr / "run-00"
    rd.mkdir()
    (rd / "grading.json").write_text(json.dumps({"verdict": "PASS"}), encoding="utf-8")
    entry = {
        "index": 0, "description": "d", "repo": "r", "runner": "claude",
        "model": "opus", "channel": "clone", "mode": "A",
        "run_dir": str(rd), "target_dir": str(rd / "target"),
        "pid": None, "terminal_state": "COMPLETED", "expect": {},
    }
    outcome = PR._collect_one_run_detached(entry, hr)
